  --color-text:         #1d1d1f;
  --color-text-muted:   #6e6e73;
  --color-accent:       #0071e3;
  --color-accent-hover: #0077ed;
  --color-danger:       #c0392b;
  --color-danger-hover: #a93226;
  --color-danger-bg:    #fdf3f2;
  --color-focus-ring:   #0071e3;
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  18px;
  --shadow-card: 0 2px 12px rgba(0,0,0,.08), 0 1px 3px rgba(0,0,0,.06);
  --shadow-modal: 0 24px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.10);
  --transition: 160ms ease;
}

html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ── Skip link ────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; outline: 3px solid var(--color-focus-ring); outline-offset: 2px; }

/* ── Focus visible ────────────────────────────────────────── */
:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* ── Layout ───────────────────────────────────────────────── */
.site-header {
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  padding: 0 2rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header__brand {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
  text-decoration: none;
}

.site-header__nav { display: flex; gap: .25rem; }

.site-header__nav a {
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  text-decoration: none;
  padding: .375rem .75rem;
  border-radius: var(--radius-sm);
  transition: background var(--transition), color var(--transition);
}
.site-header__nav a:hover { background: var(--color-surface-2); color: var(--color-text); }
.site-header__nav a[aria-current="page"] { color: var(--color-accent); }

main {
  flex: 1;
  padding: 3rem 2rem;
  max-width: 960px;
  width: 100%;
  margin: 0 auto;
}

/* ── Page heading ─────────────────────────────────────────── */
.page-heading {
  margin-bottom: 2.5rem;
}
.page-heading h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -.025em;
  margin-bottom: .375rem;
}
.page-heading p { color: var(--color-text-muted); font-size: .9375rem; }

/* ── Image card ───────────────────────────────────────────── */
.image-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr;
  max-width: 620px;
}

.image-card__preview {
  background: var(--color-surface-2);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.image-card__preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-card__body {
  padding: 1.25rem 1.5rem 1.5rem;
}

.image-card__meta {
  display: flex;
  flex-direction: column;
  gap: .25rem;
  margin-bottom: 1.25rem;
}

.image-card__title {
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: -.01em;
}

.image-card__info {
  font-size: .8125rem;
  color: var(--color-text-muted);
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.image-card__actions {
  display: flex;
  gap: .625rem;
  flex-wrap: wrap;
}

/* ── Buttons ──────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .4375rem;
  padding: .5rem 1.125rem;
  font-size: .875rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  text-decoration: none;
  white-space: nowrap;
}

.btn--primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}
.btn--primary:hover { background: var(--color-accent-hover); border-color: var(--color-accent-hover); }

.btn--ghost {
  background: transparent;
  color: var(--color-text-muted);
  border-color: var(--color-border);
}
.btn--ghost:hover { background: var(--color-surface-2); color: var(--color-text); }

.btn--danger {
  background: transparent;
  color: var(--color-danger);
  border-color: var(--color-danger);
}
.btn--danger:hover { background: var(--color-danger-bg); }

/* dialog confirm buttons */
.btn--danger-filled {
  background: var(--color-danger);
  color: #fff;
  border-color: var(--color-danger);
}
.btn--danger-filled:hover { background: var(--color-danger-hover); border-color: var(--color-danger-hover); }

.btn svg { flex-shrink: 0; }

/* ── Modal backdrop ───────────────────────────────────────── */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 1000;
  /* hidden state */
  opacity: 0;
  visibility: hidden;
  transition: opacity 200ms ease, visibility 200ms ease;
}

.modal-backdrop.is-open {
  opacity: 1;
  visibility: visible;
}

/* ── Modal dialog ─────────────────────────────────────────── */
.modal {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-modal);
  width: 100%;
  max-width: 440px;
  padding: 2rem;
  position: relative;
  transform: scale(.95) translateY(8px);
  transition: transform 200ms ease;
}

.modal-backdrop.is-open .modal {
  transform: scale(1) translateY(0);
}

.modal__icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-danger-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-danger);
}

.modal__title {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -.015em;
  margin-bottom: .625rem;
}

.modal__body {
  font-size: .9375rem;
  color: var(--color-text-muted);
  line-height: 1.55;
  margin-bottom: 1.75rem;
}

.modal__body strong { color: var(--color-text); font-weight: 600; }

.modal__actions {
  display: flex;
  gap: .625rem;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.modal__close-x {
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  border: none;
  background: transparent;
  color: var(--color-text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), color var(--transition);
}
.modal__close-x:hover { background: var(--color-surface-2); color: var(--color-text); }

/* ── Live region ──────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 480px) {
  main { padding: 2rem 1rem; }
  .site-header { padding: 0 1rem; }
  .modal { padding: 1.5rem; }
  .modal__actions { flex-direction: column-reverse; }
  .modal__actions .btn { width: 100%; justify-content: center; }
}

/* ── Forced colors ────────────────────────────────────────── */
@media (forced-colors: active) {
  .modal-backdrop { background: rgba(0,0,0,.6); }
  .modal { border: 2px solid ButtonBorder; }
  .btn--danger { border-color: ButtonBorder; color: ButtonText; }
  .btn--danger-filled { background: ButtonText; color: ButtonFace; border-color: ButtonBorder; }
  .modal__close-x { color: ButtonText; }
  .modal__icon { background: Canvas; }
  .modal__icon svg { color: ButtonText; }
}
