  'use strict';

  const backdrop = document.getElementById('delete-modal-backdrop');
  const dialog   = document.getElementById('delete-modal');
  const triggers = document.querySelectorAll('.trigger[data-modal="delete-modal"]');
  const cancelBtn  = document.getElementById('modal-cancel');
  const confirmBtn = document.getElementById('modal-confirm');
  const closeXBtn  = document.getElementById('modal-close-x');
  const statusRegion = document.getElementById('status-region');

  // The element that triggered the modal — used to restore focus on close
  let triggerElement = null;

  // All focusable elements inside the dialog
  const FOCUSABLE = [
    'a[href]', 'button:not([disabled])', 'input:not([disabled])',
    'select:not([disabled])', 'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])'
  ].join(',');

  function getFocusable() {
    return [...dialog.querySelectorAll(FOCUSABLE)];
  }

  function openModal(opener) {
    triggerElement = opener;
    backdrop.classList.add('is-open');
    dialog.removeAttribute('hidden');
    backdrop.removeAttribute('inert');

    // Move focus to the first focusable element in the dialog
    requestAnimationFrame(() => {
      const focusable = getFocusable();
      if (focusable.length) focusable[0].focus();
    });
  }

  function closeModal() {
    backdrop.classList.remove('is-open');
    dialog.setAttribute('hidden', '');
    backdrop.setAttribute('inert', '');

    // Return focus to the element that opened the dialog
    if (triggerElement) {
      triggerElement.focus();
      triggerElement = null;
    }
  }

